import{_ as s,c as a,o as e,a2 as i}from"./chunks/framework.BQGPkCej.js";const u=JSON.parse('{"title":"开发者文档","description":"","frontmatter":{},"headers":[],"relativePath":"guide/quick_start/index.md","filePath":"guide/quick_start/index.md","lastUpdated":1720634491000}'),t={name:"guide/quick_start/index.md"},n=i('<h1 id="开发者文档" tabindex="-1">开发者文档 <a class="header-anchor" href="#开发者文档" aria-label="Permalink to &quot;开发者文档&quot;">​</a></h1><p>本篇文档主要面向与开发者提供，无论你是想基于 <code>Adachi-BOT</code> 自行开发相关功能插件，又或是为本项目提供贡献，我们都强烈建议你阅读本篇文档内容。</p><h2 id="启动项目" tabindex="-1">启动项目 <a class="header-anchor" href="#启动项目" aria-label="Permalink to &quot;启动项目&quot;">​</a></h2><p>在部署完成项目后（与用户部署无异），执行此命令来以开发者模式启动项目：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span></code></pre></div><p>开发模式相较其他有下面几点不同：</p><ul><li><s>代码变动后自动重载项目</s>（因为某 <code>puppeteer</code> 不会正常退出导致内存占用爆满而暂时弃用）</li><li>自动热更新的 <code>web-console</code> 开发体验</li><li>较高的系统占用开销</li></ul><p>需要注意的是，当开启 <code>webconsole.yml -&gt; enable</code> 时，需要事先进入 <code>scr/web-console/frontend</code> 执行 <code>pnpm install</code> 命令，否则将会启动报错。</p><p><s>不能自动重载的话似乎与 <code>pnpm start</code> 没什么区别，如果不打算开发 <code>web-console</code> 的话使用 <code>pnpm start</code> 可能更好一点</s></p><h2 id="其他-cli-命令" tabindex="-1">其他 cli 命令 <a class="header-anchor" href="#其他-cli-命令" aria-label="Permalink to &quot;其他 cli 命令&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # 生产环境启动，自动更新下载 web-console 静态资源</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> serve</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # 使用 pm2 以后台模式启动生产环境项目</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> restart</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # 重启通过 `pnpm serve` 启动的项目</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stop</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # 停止并删除 `pnpm serve` 启动的项目</span></span></code></pre></div>',11),p=[n];function l(d,h,o,c,r,k){return e(),a("div",null,p)}const _=s(t,[["render",l]]);export{u as __pageData,_ as default};
